package com.bank.lineage.core;

import java.util.*;
import java.util.function.Function;
import java.util.logging.Logger;

// An RDD that records lineage and recovers lost partitions by replaying it.
public class LineageRdd<T> {
    private static final Logger log = Logger.getLogger(LineageRdd.class.getName());

    private List<List<T>> baseData;                 // non-null only for root/checkpoint
    private LineageRdd<Object> parent;              // lineage link (null when truncated)
    private Function<List<Object>, List<T>> recipe; // how to derive from parent
    private final int numPartitions;

    // In-memory cache of computed partitions (can be "lost").
    private final Map<Integer, List<T>> cache = new HashMap<>();

    public LineageRdd(List<List<T>> baseData) {
        this.baseData = baseData;
        this.numPartitions = baseData.size();
    }

    @SuppressWarnings("unchecked")
    private LineageRdd(LineageRdd<?> parent, Function<List<Object>, List<T>> recipe, int n) {
        this.parent = (LineageRdd<Object>) parent;
        this.recipe = recipe;
        this.numPartitions = n;
    }

    public int numPartitions() { return numPartitions; }

    // Lazy transformation — records lineage.
    public <R> LineageRdd<R> map(Function<T, R> f) {
        return new LineageRdd<>(this, in -> {
            List<R> out = new ArrayList<>();
            for (Object o : in) { @SuppressWarnings("unchecked") T t = (T) o; out.add(f.apply(t)); }
            return out;
        }, numPartitions);
    }

    @SuppressWarnings("unchecked")
    public LineageRdd<T> filter(java.util.function.Predicate<T> p) {
        return new LineageRdd<>(this, in -> {
            List<T> out = new ArrayList<>();
            for (Object o : in) { T t = (T) o; if (p.test(t)) out.add(t); }
            return out;
        }, numPartitions);
    }

    // Compute a partition, using cache if present, else replay lineage.
    @SuppressWarnings("unchecked")
    public List<T> compute(int p) {
        if (cache.containsKey(p)) return cache.get(p);
        List<T> result;
        if (baseData != null) {
            result = new ArrayList<>(baseData.get(p));
        } else {
            List<Object> parentPart = (List<Object>) parent.compute(p);
            log.fine(() -> "replaying recipe for partition " + p + " from parent");
            result = recipe.apply(parentPart);
        }
        cache.put(p, result);
        return result;
    }

    // Simulate an executor failure that loses a cached partition.
    public void losePartition(int p) {
        log.severe(() -> "executor failure: cached partition " + p + " LOST");
        cache.remove(p);
        if (parent != null) parent.cache.remove(p); // parent cache on that executor lost too
    }

    // Recover only the lost partitions by recomputing from lineage.
    public void recoverLostPartitions(Set<Integer> lost) {
        for (int p : lost) {
            log.info(() -> "recomputing ONLY partition " + p + " from lineage (not whole job)");
            compute(p);
        }
    }

    // Checkpoint: materialize all partitions to "reliable storage" and truncate lineage.
    public void checkpoint() {
        log.info("checkpoint: materializing to reliable storage and truncating lineage");
        List<List<T>> materialized = new ArrayList<>();
        for (int p = 0; p < numPartitions; p++) materialized.add(compute(p));
        this.baseData = materialized; // now a root
        this.parent = null;           // lineage truncated — recovery becomes shallow
        this.recipe = null;
    }
}
