package com.bank.lineage;

import com.bank.lineage.core.LineageRdd;
import com.bank.lineage.model.Txn;
import java.math.BigDecimal;
import java.util.Set;
import java.util.logging.*;

public class LineageDemo {
    private static final Logger log = Logger.getLogger(LineageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new LineageLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        LineageRdd<Txn> base = new LineageRdd<>(java.util.List.of(
            java.util.List.of(new Txn("SAV2001", new BigDecimal("1000")),
                              new Txn("CUR3001", new BigDecimal("500"))),
            java.util.List.of(new Txn("SAV2001", new BigDecimal("3000")))
        ));

        // Long-ish lineage: filter Rajesh, map amount.
        LineageRdd<BigDecimal> rajesh = base
            .filter(t -> t.getAccountId().equals("SAV2001"))
            .map(Txn::getAmount);

        // Compute both partitions (caches them).
        log.info(() -> "p0=" + rajesh.compute(0) + ", p1=" + rajesh.compute(1));

        // Executor dies: partition 1 is lost.
        rajesh.losePartition(1);

        // Recover ONLY partition 1 from lineage.
        rajesh.recoverLostPartitions(Set.of(1));
        log.info(() -> "after recovery p1=" + rajesh.compute(1));

        // Checkpoint to truncate lineage; future recovery is shallow.
        rajesh.checkpoint();
        rajesh.losePartition(0);
        rajesh.recoverLostPartitions(Set.of(0)); // now reads from checkpoint, not full recipe
        log.info(() -> "after checkpointed recovery p0=" + rajesh.compute(0));
    }
}

